import{_ as a,H as n,f as r,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"致谢","description":"","frontmatter":{},"headers":[],"relativePath":"黑客与画家/致谢.md","filePath":"黑客与画家/致谢.md","lastUpdated":1795561874000}'),o={name:"黑客与画家/致谢.md"};function t(l,e,s,d,p,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h1><p>我首先要感谢的人是 Sarah Harlin。每当写完一篇文章，我通常会先给她看。她总是会删去一半，然后告诉我重写另一半。她对文章节奏的把握堪称完美，不放过任何一句废话，就像猎狗不放过麻雀一样。</p><p>如果本书写得不算糟，那主要归功于我与她之间的交流，以及我与罗伯特·莫里斯、特雷弗·布莱克韦尔、杰基·麦克唐纳之间的交流。我很幸运，能够认识他们。</p><p>其他一些朋友的思想也让我受益匪浅。本书涉及的主要问题都是在过去几年中与他们深入讨论过的。这些朋友是 Ken Anderson、Chip Coldwell、Matthias Felleisen、Dan Friedman、Daniel Giffin、Shiro Kawai、Lisa Randall、Eric Raymond、Olin Shivers、Bob van derZwaan 和 David Weinberger。我尤其感谢 Eric Raymond，不仅因为他的思想令我受教，还因</p><ul><li>1</li></ul><p>为他关于黑客的文章</p><ul><li>为我提供了如何写这个主题的范例。</li></ul><p>我还要感谢许多提供帮助和启发的人。他们是 Jülide Aker、Chris Anderson、JonathanBachrach、Ingrid Bassett、Jeff Bates、Alan Bawden、Andrew Cohen、Cindy Cohn、KateCourteau、Maria Daniels、Rich Draves、Jon Erickson、John Foderaro、Bob Frankston、Erann Gat、Phil Greenspun、Ann Gregg、Amy Harmon、Andy Hertzfeld、Jeremy Hylton、Brad Karp、Shriram Krishnamurthi、Fritz Kunze、Joel Lehrer、Henry Leitner、LarryLessig、Simon London、John McCarthy、Doug McIlroy、Rob Malda、Julie Mallozzi、Matz、Larry Mihalko、Mark Nitzberg、North Shore United、Peter Norvig、Parmets 夫妇、Sesha Pratap、Joel Rainey、Jonathan Rees、Guido van Rossum、Barry Shein、Sloos 夫妇、Mike Smith、 Ryan Stanley、Guy Steele、Sam Steingold、Anton van Straaten、GregSullivan、Brad Templeton、Dave Touretzky、Mike Vanier、Weickers 夫妇、JonL White、Stephen Wolfram 和 Bill Yerazunis。</p><p>本书（英文版）装帧精美，原因是它完全出自排版大师 Gino Lee 之手，我在这方面什么忙都没帮上。我对 Gino Lee 言听计从，从他身上学到了很多关于图书设计的知识。Chip Coldwell用了几个小时安排好本书的字体，而 Amy Hendrickson 则是用了几天写出了好几个 LaTex 宏程序，使得文章排版后的格式易于阅读。令人惊奇的是，本书的封面某种意义上是莫里斯设计的，他使用图像处理软件 Gimp 对设计稿做了一些大修改。Gilberte Houbart 巧妙而执着地找到了各种需要的图片，并与分布在全世界各处的相关机构联系，获得了使用授权。</p><p>O&#39;Reilly 出版公司的工作人员非常杰出。Allen Noren 对于制作好书的真正兴趣足以使得所有人都能对出版业重新燃起希望。Betsy Waliszewski 对于如何让图书更畅销的远见卓识被我偷偷地全盘继承。Matt Hutchinson、Robert Romano 和 Claire Cloutier 使得本书的整个制作过程非常顺利。相比大型出版集团，O&#39;Reilly 这样的出版公司会令出版更精彩。</p><p>另外，特别感谢 Jessica Livingston。她的意见让本书在各个方面都得到了提高，从封面到正文无不如此。她始终为我加油打气，这也提高了本书的质量，因为她总是对我说许许多多人想读这本书，迫使我只能更努力地写作，让它不辜负那些人的期待。</p><p>我从许多人身上学到了黑客技术，但是让我学会画画的主要只有一个人——Idelle Weber。她是一名优秀的教师，特别善于用实例教学。我深深地感谢她和她的丈夫 Julian Weber，他们多年来给予了我无微不至的照顾。</p><p>最后，我要感谢我的父母。父亲教给我什么是怀疑主义，母亲教给我如何发挥想象力。有了这样的母亲，我眼前的世界就从黑白变成了彩色。</p><p>[1]：指Eric Raymond的著名文章“How To Become A Hacker”。——译者注</p>',14)])])}const u=a(o,[["render",t]]);export{c as __pageData,u as default};
